 void SetupProductionCaptureE(){world.NewGame(0);world.WalletFunds=100000;world.Hangar["fuel"]=1000;var f=world.DeployFacilityE("Laboratory");facilityE=f?.Id??"";var c=world.DeployColonyE("Temperate industrial colony");colonyE=c?.Id??"";world.WaitDocked(12);desktop.Clear();EnsureWindow(ViewMode.Production);productionTabE=captureScene switch{"stage-e-moons"=>1,"stage-e-planets"=>2,"stage-e-advanced"=>4,"stage-e-trees"=>3,_=>0};commanderItemD="e_t2";}
 int uiChecksE;
 void RunProductionUiChecksE(int frame){void Check(bool ok,string name){if(!ok)throw new Exception("STAGE E UI FAIL / "+name);uiChecksE++;Console.WriteLine("STAGE E UI PASS / "+name);}void Click(string tip)=>TestClick(ui.Hits.Last(h=>h.Tip==tip).Rect.Center.ToVector2());switch(frame){
 case 0:Check(desktop.Any(w=>w.Kind==ViewMode.Production),"Workspace opens");Click("Stage E tab / Planetary colonies");break;
 case 1:Check(ui.Hits.Any(h=>h.Tip=="Stage E upgrade colony"),"Colony diagnostics and upgrade controls");Click("Stage E upgrade colony");Check(world.Production.Colonies.Single().LinkRate==100,"Upgrade button changes throughput");Click("Stage E coolant export");Check(world.Hangar.GetValueOrDefault("e_coolant")>0,"Customs export button moves real goods");Click("Stage E tab / Advanced resources");break;
 case 2:Click("Stage E supply / e_formula");Check(world.Hangar.GetValueOrDefault("e_formula")==1,"Specialist purchase consumes funds and creates item");Click("Stage E tab / Facilities / jobs");break;
 case 3:world.Hangar["e_polymer"]=10;world.Hangar["e_coolant"]=10;world.Hangar["ind_34"]=50;Click("Stage E install / component");Check(world.Production.Jobs.Single().State=="Active","Install button creates durable job");break;
 case 4:Click("Stage E wait");Check(world.Production.Jobs.Single().State=="Ready","Strategic wait completes job");break;
 case 5:Click("Stage E deliver / "+world.Production.Jobs.Single().Id);Check(world.Hangar.GetValueOrDefault("e_component")==5,"Delivery button awards real component output");Click("Stage E tab / Production trees");break;
 case 6:Click("Stage E tree / e_t2");Check(world.ProductionTreeE("e_t2",1).Count>2,"Nested production tree is reachable");Console.WriteLine(uiChecksE+" Stage E UI checks passed.");break;}}

